参考代码 <pre><code>tree merge(tree a,tree b){
    if(!a)
        return b;
    if(!b)
        return a;
    if(a-&gt;val&gt;b-&gt;val)
        swap(a,b);
    tree root=a;
    stack&lt;tree&gt;stk;
    while(a-&gt;rs&amp;&amp;b) {
        if (a-&gt;rs-&gt;val&gt;b-&gt;val)
            swap(a-&gt;rs,b);
        stk.push(a);
        a=a-&gt;rs;
    }
    if(!a-&gt;rs){
        a-&gt;rs=b;
        stk.push(a);
    }
    while(stk.size()){
        a=stk.top();
        stk.pop();
        swap(a-&gt;ls,a-&gt;rs);
    }
    return root;
}
</code></pre>
